@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner {
  + linkedInAccount : string
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string[]
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + orderDateAndTime : datetime
  + latestDeliveryTime : datetime
  + numberOfPeople : int
  + entertainmentType : string
  + duration : time
}

class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
}

class Availability {
  + day : string
  + isAvailable : boolean
}

User "1" -- "0..*" Order : makes
Order "*" -- "1..*" Pizza : contains
BusinessOwner "1" -- "0..*" PizzaRestaurant : owns
PizzaRestaurant "*" -- "0..*" Pizza : offers
Entertainer "1" -- "0..*" Availability : has

@enduml

